\newcommand{\myHemiSphere}[5]{
	\begin{scope}[scale=#5]
		\coordinate (O) at (0,0,0);
		\coordinate (A) at (#1,0,0);
		\coordinate (B) at (-#1,0,0);
		\coordinate (S) at (0,#2,0);

		% Base/Top
		\draw[draw=none, fill=none, fill opacity=#4] (O) circle (#1 and #2);

		% Circ		 
		\fill[draw=none, fill=#3!15, fill opacity=#4, left color=#3!40, right color=#3!40, middle color=#3!15,] (A) arc (0:360:#1 and #1);  		


		% Edges
			% Base
			\draw[thin, color=#3, dashed, opacity=0.5] (O)+(#1,0,0) arc (0:180:#1 and #2);
			\draw[thick, color=#3, opacity=0.5] (B) arc (180:360:#1 and #2);

			% Top
			\draw[very thick, color=#3] (A) arc (0:360:#1 and #1);

		\tkzDrawPoints[size=7, color=none, fill=#3](O);			
%		\tkzLabelPoints[below right](O);
%		\tkzLabelPoints[above](S);
%		\tkzLabelPoints[below right](A);
%		\tkzLabelPoints[below left](B);

	\end{scope}
}

